mapper.select:
SELECT 
  FROM growth_roadmaps
 WHERE streamer_id = #{streamerId}

SELECT 
  FROM growth_roadmap_generations
 WHERE id = #{generationId}

INSERT INTO growth_roadmap_generations (
    roadmap_id, source_report_id, trigger_type, status, quality,
    prompt_version, idempotency_key, requested_at
) VALUES (
    #{roadmapId}, #{sourceReportId}, #{triggerType}, #{status}, #{quality},
    #{promptVersion}, #{idempotencyKey}, #{requestedAt}
)
ON CONFLICT (idempotency_key)
DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key
RETURNING id

mapper.update:
UPDATE growth_roadmap_generations
   SET status = 'SUPERSEDED', completed_at = now()
 WHERE roadmap_id = #{roadmapId}
   AND id <> #{generationId}
   AND status IN ('WAITING_FOR_DATA', 'PENDING', 'PROCESSING')

UPDATE growth_roadmap_generations
   SET status = 'PENDING', error_code = #{errorCode}
 WHERE id = #{generationId}
   AND status = 'PROCESSING'

UPDATE growth_roadmap_generations
   SET status = 'FAILED', completed_at = #{completedAt}, error_code = #{errorCode}
 WHERE id = #{generationId}
   AND status IN ('PENDING', 'PROCESSING')

UPDATE growth_roadmaps
   SET status = CASE WHEN current_generation_id IS NULL THEN 'FAILED' ELSE 'READY' END,
       stale = current_generation_id IS NOT NULL,
       generation_error = #{errorCode}
 WHERE id = #{roadmapId}

mapper.select:
SELECT id, suggestion_id, display_order, title, content FROM growth_suggestion_actions WHERE suggestion_id IN
#{id}
ORDER BY suggestion_id, display_order, id

INSERT INTO growth_goal_suggestions (
    roadmap_id, generation_id, display_order, metric_type, target_value,
    unit, period_start, period_end, title, rationale
) VALUES (
    #{roadmapId}, #{generationId}, #{displayOrder}, #{suggestion.metricType},
    #{suggestion.targetValue}, #{suggestion.unit}, #{suggestion.periodStart},
    #{suggestion.periodEnd}, #{suggestion.title}, #{suggestion.rationale}
)
RETURNING id

mapper.update:
UPDATE growth_goal_suggestions
   SET status = 'ACCEPTED', accepted_goal_id = #{goalId},
       accepted_at = #{acceptedAt}
 WHERE id = #{suggestionId}
   AND status = 'SUGGESTED'

UPDATE growth_goal_suggestions
   SET status = 'DISMISSED', dismissed_at = #{dismissedAt}
 WHERE id = #{suggestionId}
   AND status = 'SUGGESTED'

mapper.select:
SELECT s.metric_type, s.title, s.status
  FROM growth_goal_suggestions s
  JOIN growth_roadmaps r ON r.id = s.roadmap_id
 WHERE r.streamer_id = #{streamerId}
 ORDER BY s.created_at DESC, s.id DESC
 LIMIT #{limit}
